CREATE OR REPLACE FUNCTION public.marketing_guard_active_revision()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE aid uuid; a marketing_automations%ROWTYPE;
BEGIN
 IF TG_TABLE_NAME='marketing_automation_steps' THEN
   aid:=CASE WHEN TG_OP='DELETE' THEN OLD.automation_id ELSE NEW.automation_id END;
   SELECT * INTO a FROM marketing_automations WHERE id=aid FOR UPDATE;
   IF TG_OP='UPDATE' AND NEW.automation_id IS DISTINCT FROM OLD.automation_id AND EXISTS(
     SELECT 1 FROM marketing_automations prior WHERE prior.id=OLD.automation_id AND (prior.status='active' OR EXISTS(
       SELECT 1 FROM marketing_automation_enrollments WHERE automation_id=prior.id AND status='active'))) THEN
     RAISE EXCEPTION 'Active enrollment steps cannot be moved'; END IF;
   IF a.status='active' OR EXISTS(SELECT 1 FROM marketing_automation_enrollments WHERE automation_id=aid AND status='active') THEN
     RAISE EXCEPTION 'Active enrollment revisions cannot be edited'; END IF;
 ELSE
   IF TG_OP='INSERT' THEN
     IF NEW.status='active' THEN RAISE EXCEPTION 'Create a draft before activation'; END IF;
     RETURN NEW;
   END IF;
   a:=OLD;
   IF TG_OP='UPDATE' AND NEW.business_id IS DISTINCT FROM OLD.business_id THEN RAISE EXCEPTION 'Journey tenant cannot change'; END IF;
   IF TG_OP='DELETE' AND a.id='5bb1d74b-8634-4fec-9c42-f6f13cc1c33f' THEN RAISE EXCEPTION 'Review draft deletion is not approved'; END IF;
   IF TG_OP='UPDATE' THEN
     IF (a.status='active' OR EXISTS(SELECT 1 FROM marketing_automation_enrollments WHERE automation_id=a.id AND status='active')) AND
       (NEW.name,NEW.description,NEW.trigger_type,NEW.trigger_config) IS DISTINCT FROM (OLD.name,OLD.description,OLD.trigger_type,OLD.trigger_config) THEN
       RAISE EXCEPTION 'Active enrollment revisions cannot be edited'; END IF;
     IF NEW.status='active' AND OLD.status IS DISTINCT FROM 'active' THEN
       PERFORM marketing_assert_editor(NEW.business_id);
       IF NOT EXISTS(SELECT 1 FROM marketing_automation_revisions r WHERE r.automation_id=NEW.id AND r.revision=NEW.revision
         AND (r.snapshot->'automation'->>'name',r.snapshot->'automation'->>'description',r.snapshot->'automation'->>'trigger_type',r.snapshot->'automation'->'trigger_config') IS NOT DISTINCT FROM
             (NEW.name,NEW.description,NEW.trigger_type,NEW.trigger_config)
         AND r.snapshot->'steps'=(SELECT coalesce(jsonb_agg(jsonb_build_object('step_type',step_type,'config',config) ORDER BY position),'[]') FROM marketing_automation_steps WHERE automation_id=NEW.id AND business_id=NEW.business_id)
         AND r.snapshot->'templates'=marketing_revision_templates(NEW.business_id,r.snapshot->'steps')) THEN
         RAISE EXCEPTION 'Save and review the current content before activation';
       END IF;
       IF NEW.revision<1 OR NOT EXISTS(SELECT 1 FROM marketing_automation_revisions WHERE automation_id=NEW.id AND revision=NEW.revision) OR NOT EXISTS(SELECT 1 FROM marketing_automation_steps WHERE automation_id=NEW.id AND step_type='send_email') THEN
         RAISE EXCEPTION 'Save and review a valid revision before activation'; END IF;
       IF EXISTS(SELECT 1 FROM marketing_automation_steps WHERE automation_id=NEW.id AND
         ((step_type IN ('generate_voucher','generate_promo') AND NOT marketing_offer_allowed(NEW.business_id,NEW.id,step_type,config)) OR
          (step_type='send_email' AND NOT EXISTS(SELECT 1 FROM marketing_templates t WHERE t.id=template_id AND t.business_id=NEW.business_id AND length(btrim(t.html_content))>0)) OR
          (step_type='delay' AND (CASE WHEN coalesce(config->>'duration','') ~ '^[0-9]+([.][0-9]+)?$' THEN (config->>'duration')::numeric<=0 ELSE true END OR coalesce(config->>'unit','') NOT IN ('minutes','hours','days'))) OR
          (step_type='condition' AND coalesce(config->>'condition_type','') NOT IN ('has_tag','opened_email','clicked_link')))) THEN
          RAISE EXCEPTION 'Missing content or unsupported step. Voucher/promo issuance requires separately approved limits.'; END IF;
       IF NEW.trigger_type='tag_added' AND NEW.trigger_config->>'tag'='completed-tour' AND EXISTS(
          SELECT 1 FROM marketing_automation_steps WHERE automation_id=NEW.id AND step_type='condition' AND config->>'condition_type'='opened_email') THEN
          RAISE EXCEPTION 'Review invitations cannot depend on email opens. Review completion is unavailable.'; END IF;
       IF NOT EXISTS(SELECT 1 FROM marketing_contacts c WHERE c.business_id=NEW.business_id AND marketing_eligibility(NEW.business_id,c.id)='eligible') THEN
          RAISE EXCEPTION 'No contacts have verified email-marketing permission. Approve the collection notice and evidence first.'; END IF;
     END IF;
   END IF;
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END $function$

CREATE OR REPLACE FUNCTION public.marketing_policy_reason(p_business_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE p marketing_delivery_policy%ROWTYPE; zone text; local_time time;
BEGIN
 SELECT * INTO p FROM marketing_delivery_policy WHERE business_id=p_business_id;
 IF NOT FOUND OR NOT p.enabled OR p.approved_at>clock_timestamp() THEN RETURN 'policy_approval_pending'; END IF;
 SELECT timezone INTO zone FROM businesses WHERE id=p_business_id;
 -- Named zones only: do not guess the operator's location or use the worker's clock zone.
 IF zone IS NULL OR zone NOT LIKE '%/%' OR NOT EXISTS(SELECT 1 FROM pg_timezone_names WHERE name=zone) THEN
   RETURN 'timezone_unavailable'; END IF;
 local_time:=(clock_timestamp() AT TIME ZONE zone)::time;
 IF local_time<p.window_start OR local_time>=p.window_end THEN RETURN 'quiet_hours'; END IF;
 RETURN 'eligible';
END $function$

CREATE OR REPLACE FUNCTION public.marketing_step_eligibility(p_business_id uuid, p_contact_id uuid, p_enrollment_id uuid DEFAULT NULL::uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE reason text; a marketing_automations%ROWTYPE; e marketing_automation_enrollments%ROWTYPE;
BEGIN
 reason:=marketing_eligibility(p_business_id,p_contact_id);
 IF reason<>'eligible' THEN RETURN reason; END IF;
 IF p_enrollment_id IS NOT NULL THEN
   SELECT * INTO e FROM marketing_automation_enrollments WHERE id=p_enrollment_id AND business_id=p_business_id AND contact_id=p_contact_id;
   IF NOT FOUND OR e.status<>'active' THEN RETURN 'enrollment_inactive'; END IF;
   SELECT * INTO a FROM marketing_automations WHERE id=e.automation_id AND business_id=p_business_id;
   IF NOT FOUND OR a.status<>'active' THEN RETURN 'journey_paused'; END IF;
   IF a.trigger_type='contact_added' AND NOT EXISTS(SELECT 1 FROM marketing_delivery_policy
      WHERE business_id=p_business_id AND nullif(btrim(first_booking_rule_ref),'') IS NOT NULL) THEN RETURN 'first_booking_policy_pending'; END IF;
   IF EXISTS(SELECT 1 FROM marketing_automation_steps WHERE automation_id=a.id AND business_id=p_business_id
      AND step_type IN ('generate_voucher','generate_promo')) THEN RETURN 'offer_issuance_unavailable'; END IF;
   IF a.trigger_type IN ('date_field','post_booking') THEN RETURN 'domain_event_binding_unavailable'; END IF;
   -- These tags are not bound to verified domain events in the current engine.
   IF a.trigger_type='tag_added' AND a.trigger_config->>'tag' IN ('completed-tour','left-review','photos-ready','anniversary-1yr','vip') THEN
      RETURN 'domain_event_binding_unavailable'; END IF;
   IF a.trigger_type='tag_added' AND a.trigger_config->>'tag'='voucher-expiring-30d' THEN RETURN 'voucher_expiry_schedule_unavailable'; END IF;
   IF nullif(e.metadata->>'voucher_code','') IS NOT NULL AND NOT EXISTS(
     SELECT 1 FROM vouchers v JOIN marketing_contacts c ON c.id=p_contact_id AND c.business_id=v.business_id
     WHERE v.business_id=p_business_id AND v.code=e.metadata->>'voucher_code' AND v.status='ACTIVE' AND v.current_balance>0
       AND (v.expires_at IS NULL OR v.expires_at>now()) AND lower(btrim(v.recipient_email))=lower(btrim(c.email))) THEN RETURN 'voucher_ineligible'; END IF;
   IF nullif(e.metadata->>'promo_code','') IS NOT NULL AND NOT EXISTS(
     SELECT 1 FROM promotions p WHERE p.business_id=p_business_id AND p.code=e.metadata->>'promo_code' AND p.active
       AND (p.valid_from IS NULL OR p.valid_from<=now()) AND (p.valid_until IS NULL OR p.valid_until>now())
       AND (p.max_uses IS NULL OR coalesce(p.used_count,0)<p.max_uses)) THEN RETURN 'promo_ineligible'; END IF;
   IF a.trigger_type='contact_added' AND marketing_has_reservation(p_business_id,p_contact_id) THEN RETURN 'already_booked'; END IF;
   IF a.trigger_type='booking_inactive' AND (marketing_has_reservation(p_business_id,p_contact_id,(e.metadata->>'last_booking_at')::timestamptz)
      OR NOT welcome_back_contact_eligible(p_business_id,p_contact_id,(e.metadata->>'last_booking_at')::timestamptz)) THEN RETURN 'rebooked_or_upcoming'; END IF;
 END IF;
 RETURN 'eligible';
END $function$

CREATE OR REPLACE FUNCTION public.validate_welcome_back_enrollment(p_enrollment_id uuid, p_business_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE e marketing_automation_enrollments%ROWTYPE; a marketing_automations%ROWTYPE;
BEGIN
  SELECT * INTO e FROM marketing_automation_enrollments WHERE id=p_enrollment_id AND business_id=p_business_id FOR UPDATE;
  IF NOT FOUND OR e.status <> 'active' THEN RETURN false; END IF;
  SELECT * INTO a FROM marketing_automations WHERE id=e.automation_id AND business_id=e.business_id;
  IF NOT FOUND OR a.status <> 'active' THEN RETURN false; END IF;
  IF a.trigger_type <> 'booking_inactive' THEN RETURN true; END IF;
  IF NOT COALESCE(welcome_back_contact_eligible(e.business_id,e.contact_id,(e.metadata->>'last_booking_at')::timestamptz),false) THEN
    UPDATE marketing_automation_enrollments SET status='exited',updated_at=now() WHERE id=e.id;
    RETURN false;
  END IF;
  RETURN true;
END $function$
